std::atomic<HWND> g_wnd;
std::atomic<UINT> g_pendingBits;
std::atomic<bool> g_refreshPosted;

void RequestRefresh(UINT bits) {
    g_pendingBits |= bits;
    HWND wnd = g_wnd;
    if (wnd && !g_refreshPosted.exchange(true)) {
        PostMessageW(wnd, WM_APP_REFRESH, 0, 0);
    }
}

